using Avalonia.Controls;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop; public sealed partial class ManagerIntegrationsWindow : Window { private readonly IIntegrationManager manager; private readonly Guid organizationId; public ManagerIntegrationsWindow() => throw new InvalidOperationException("Integration runtime is required."); public ManagerIntegrationsWindow(IIntegrationManager manager, Guid organizationId) { this.manager = manager ?? throw new ArgumentNullException(nameof(manager)); if (organizationId == Guid.Empty) throw new ArgumentException("Organization is required."); this.organizationId = organizationId; InitializeComponent(); ScopeText.Text = $"Organization {organizationId:D}"; Opened += async (_, _) => await Refresh(); } private async void RefreshClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Refresh(); private async void CreateClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Execute(async () => { await manager.CreateAsync(organizationId, ProviderBox.Text ?? "", NameBox.Text ?? "", EndpointBox.Text ?? "", SecretBox.Text ?? "", Guid.NewGuid(), default); await Refresh(); }); private async Task Refresh() => await Execute(async () => { var c = await manager.ConnectionsAsync(organizationId, default); var w = await manager.WebhooksAsync(organizationId, default); ConnectionList.ItemsSource = c.Items.Select(x => $"{x.DisplayName} · {x.Provider} · {x.Status} · {x.Endpoint}").ToArray(); WebhookList.ItemsSource = w.Items.Select(x => $"{x.EventType} · {x.Status} · attempts {x.AttemptCount} · HTTP {x.LastStatusCode?.ToString() ?? "-"}").ToArray(); }); private async Task Execute(Func<Task> a) { try { await a(); MessageText.Text = ""; } catch (Exception ex) when (ex is ArgumentException or InvalidOperationException or HttpRequestException) { MessageText.Text = ex is HttpRequestException ? "Integration service request failed." : ex.Message; } } }
